config.http-snippet:
proxy_cache_path /tmp/registry-read-cache levels=1:2 keys_zone=registry_read_cache:20m max_size=1g inactive=5m use_temp_path=off;
map "$request_method:$uri" $registry_read_cache_zone {
    default off;
    ~^GET:/v0(?:\.1)?/servers$ registry_read_cache;
}
keepalive_time 60s;

# Public listing responses contain no user-specific data. Leave credentials/cookies uncompressed.
map "$request_method:$host:$uri:$http_authorization:$http_cookie" $registry_public_json_gzip {
    default 0;
    ~^(GET|HEAD):(registry\.modelcontextprotocol\.io|prod\.registry\.modelcontextprotocol\.io|staging\.registry\.modelcontextprotocol\.io|fixture\.gateway-canary\.invalid):/v0(?:\.1)?/servers::$ 1;
}

config.location-snippet:
proxy_cache $registry_read_cache_zone;
proxy_cache_key "$scheme$request_method$host$request_uri";
proxy_cache_valid 200 30s;
proxy_cache_lock on;
proxy_cache_lock_timeout 5s;
proxy_cache_background_update on;
proxy_cache_use_stale updating error timeout http_500 http_502 http_503 http_504;
add_header X-Registry-Cache $upstream_cache_status always;

# Compress the public JSON representation after cache lookup; preserve identity fallback.
gzip off;
gzip_types application/json;
gzip_min_length 1024;
gzip_comp_level 1;
gzip_proxied any;
gzip_vary on;
if ($registry_public_json_gzip) {
    gzip on;
}
